/// Bounded cache for compiled vectorscan regexps. Old entries are evicted in
/// least-recently-used order once the cache reaches its capacity, so the cache
/// does not grow without limit under diverse patterns.
class RegexpsCache
{
public:
    explicit RegexpsCache(size_t max_size_) : max_size(max_size_) { }

    template <bool save_indices, bool WithEditDistance>
    std::shared_ptr<Regexps> getOrCompile(const std::vector<String> & str_patterns, std::optional<UInt32> edit_distance);

    size_t maxSize() const { return max_size; }

private:
    using Key = std::pair<std::vector<String>, std::optional<UInt32>>;

    struct Entry
    {
        std::shared_ptr<Regexps> regexps;
        std::list<Key>::iterator lru_it;
    };

    const size_t max_size;
    std::mutex mutex;
    /// Keys ordered from least to most recently used.
    std::list<Key> lru;
    std::map<Key, Entry> storage;
};

